insert into public.gp_emp_sop (id, title, icon, sort, intro, steps, audience, version, active, updated_by, updated_at) values
  ($q$sop-general$q$, $q$General$q$, $q$📋$q$, 10, $q$Rules for every person on the workshop floor, on every car — customer, workshop, showroom or Bos. (Handbook Part 1, 2.2–2.4)
Peraturan untuk setiap orang di lantai kerja, untuk setiap kereta.$q$, $q$[{"text": "Only discipline and consistency will get us far. Treat every car like it is your own — be gentle and precise.", "bm": "Hanya disiplin dan konsistensi akan membawa kita jauh. Layan setiap kereta seperti kereta sendiri. Berhati-hati dan teliti.", "photo": "", "video": ""}, {"text": "8:30 AM standing by and ready — not walking in the gate. Tell the manager BEFORE 8:30 if you will be late or absent.", "bm": "8:30 pagi bersedia — bukan baru masuk pagar. Beritahu pengurus SEBELUM 8:30 jika anda akan lewat atau tidak hadir. Sebelum, bukan selepas.", "photo": "", "video": ""}, {"text": "Company uniform and sports pants, clean and presentable. Proper shoes — no slippers on the shop floor.", "bm": "Pakaian seragam syarikat dan seluar sukan. Bersih dan kemas. Kasut yang sesuai. Tiada selipar di lantai kerja.", "photo": "", "video": ""}, {"text": "No watch, no ring, no bracelet when working on a car. Metal scratches paint in one second.", "bm": "Tiada jam tangan, cincin atau gelang semasa bekerja pada kereta. Logam mencalar cat dalam sesaat.", "photo": "", "video": ""}, {"text": "Fingernails cut SHORT and clean. Black powder-free gloves for polishing, coating and waxing. Wash your hands before any interior work.", "bm": "Kuku dipotong PENDEK dan bersih. Sarung tangan hitam bebas serbuk untuk menggilap, menyalut dan mengilat. Basuh tangan sebelum sebarang kerja dalaman.", "photo": "", "video": ""}, {"text": "Never press a button, switch or control with your fingernail. Keep the finger straight and press flat with the pad — a nail mark is permanent and the part has to be replaced.", "bm": "Jangan sekali-kali tekan butang, suis atau kawalan menggunakan kuku. Pastikan jari lurus dan tekan rata dengan tapak jari. Kesan kuku kekal - bahagian itu terpaksa diganti.", "photo": "", "video": ""}, {"text": "Belt buckles scratch — never lean your body against a car. Take your phone out of your chest pocket before you bend over a panel.", "bm": "Kepala tali pinggang mencalar. Jangan sekali-kali sandarkan badan pada kereta. Keluarkan telefon dari poket dada sebelum anda tunduk di atas panel.", "photo": "", "video": ""}, {"text": "Nothing is placed on a car. No eating or drinking inside a customer car. Do not sit in a customer car unless the job needs it. Do not slam doors.", "bm": "Tiada apa-apa diletakkan di atas kereta. Jangan makan atau minum dalam kereta pelanggan. Jangan duduk dalam kereta pelanggan melainkan kerja itu memerlukannya. Jangan hempas pintu.", "photo": "", "video": ""}, {"text": "Fit the plastic seat protector on the driver seat BEFORE anyone sits in it. It stays on the whole time the car is with us — remove it only at final handover.", "bm": "Tempat duduk pemandu mesti sentiasa dipasang pelapik plastik sebelum sesiapa duduk di atasnya. Ia kekal dipasang sepanjang kereta berada dengan kami. Tanggalkan hanya semasa penyerahan akhir.", "photo": "", "video": ""}, {"text": "Bags, shoes, helmets and boxes go on the carpet, never on the seat. Never place tools, machines, cloths or chemicals on any seat or panel.", "bm": "Beg, kasut, topi keledar dan kotak diletakkan di atas karpet. Jangan sekali-kali di atas tempat duduk. Jangan sekali-kali letak alat, mesin, kain atau bahan kimia di atas mana-mana tempat duduk atau panel.", "photo": "", "video": ""}, {"text": "Customer items: photograph before you move them, put them in a basket, return them matching the photo.", "bm": "Barang pelanggan: ambil gambar sebelum alih, letak dalam bakul, pulangkan mengikut gambar.", "photo": "", "video": ""}, {"text": "Greet every customer — raise your hand and say “Hello Bos, welcome to GrandLab”. Everyone, whenever eyes meet, not just reception.", "bm": "Beri salam kepada setiap pelanggan - angkat tangan dan ucap “Hello Bos, welcome to GrandLab”. Semua orang, setiap kali bertentang mata, bukan kaunter sahaja.", "photo": "", "video": ""}, {"text": "No phone in your hand where customers can see you. Never discuss prices, other customers or complaints within earshot of a customer.", "bm": "Tiada telefon di tangan di tempat pelanggan boleh nampak. Jangan sekali-kali bincang harga, pelanggan lain atau aduan dalam jarak dengar pelanggan.", "photo": "", "video": ""}, {"text": "Floor staff never take keys or answer price questions. Escalate by ROLE: QC person, then Sales Advisor, then Receptionist, then Manager.", "bm": "Kakitangan lantai tidak mengambil kunci atau menjawab soalan harga. Tingkatkan mengikut PERANAN: petugas QC, kemudian Sales Advisor, kemudian Penyambut Tetamu, kemudian Pengurus.", "photo": "", "video": ""}, {"text": "Never keep silent about a mistake. Nobody is fined for spoiled film or wasted product — HIDING IT is the only offence. Log every redo on the spot, with the real reason.", "bm": "Jangan sekali-kali berdiam diri tentang kesilapan. Tiada sesiapa didenda kerana filem rosak atau produk terbazir. MENYEMBUNYIKANNYA sahaja yang menjadi kesalahan. Setiap kerja ulang direkodkan serta-merta, dengan sebab yang sebenar.", "photo": "", "video": ""}, {"text": "Chemicals are pre-diluted by the MIXER OF THE DAY — nobody else mixes. Labels face out. If a bottle is unlabelled or you are not sure what is in it, do not use it. Ask.", "bm": "Bahan kimia dicairkan terlebih dahulu oleh PENCAMPUR HARI ITU. Tiada orang lain mencampur. Label menghadap ke luar. Jika botol tiada label atau anda tidak pasti isinya, jangan guna. Tanya.", "photo": "", "video": ""}, {"text": "Everything goes back to its home within 30 seconds of finishing with it. Pick up any rubbish, nails, screws or sharp items you see.", "bm": "Setiap barang dikembalikan dalam masa 30 saat selepas selesai digunakan. Kutip sebarang sampah, paku, skru atau benda tajam yang anda nampak.", "photo": "", "video": ""}, {"text": "Eye protection when using a rotary, when sanding, and when spraying chemicals above shoulder height. Mask when sanding or using strong chemicals in an enclosed space.", "bm": "Pelindung mata semasa menggunakan rotary, semasa mengamplas, dan semasa menyembur bahan kimia melebihi paras bahu. Pelitup muka semasa mengamplas atau bekerja dengan bahan kimia kuat di ruang tertutup.", "photo": "", "video": ""}, {"text": "Chemical on SKIN: rinse with plenty of running water straight away. In the EYES: rinse with running water for at least 15 minutes, then go to a clinic. Tell the manager every time.", "bm": "KULIT: bilas dengan banyak air mengalir serta-merta. MATA: bilas dengan air mengalir sekurang-kurangnya 15 minit, kemudian pergi ke klinik. Beritahu pengurus setiap kali, walaupun nampak kecil.", "photo": "", "video": ""}, {"text": "Check the cable before you use any machine. Never use an electrical tool with wet hands or standing in water. Unplug before changing a pad or a disc.", "bm": "Periksa kabel sebelum anda guna mana-mana mesin. Jangan sekali-kali guna alat elektrik dengan tangan basah atau berdiri di dalam air. Cabut palam sebelum menukar pad atau cakera.", "photo": "", "video": ""}, {"text": "Water or oil on the floor: mop it immediately. Never leave a heat gun switched on and unattended. Know where the nearest fire extinguisher is BEFORE you need it.", "bm": "Air atau minyak di lantai: mop serta-merta. Jangan sekali-kali tinggalkan heat gun hidup tanpa diawasi. Ketahui di mana alat pemadam api terdekat SEBELUM anda memerlukannya.", "photo": "", "video": ""}, {"text": "6:15 PM cleanliness — 15 minutes, everybody. Your bay: all tools back in the rack, NOTHING on the floor, floor swept and mopped, cloths sorted for washing (wheel cloths separately, always).", "bm": "6:15 petang kebersihan - 15 minit, semua orang. Semua alat dikembalikan ke rak atau dulangnya. TIADA apa-apa di lantai. Lantai bay anda disapu dan dimop. Kain diasingkan untuk dibasuh - kain rim diasingkan, sentiasa.", "photo": "", "video": ""}, {"text": "Set your bay up for tomorrow BEFORE you leave: product tray stocked, machines wiped, pads cleaned, fresh cloths ready. Anything below the minimum stock line — photograph and report it tonight.", "bm": "Bay disediakan pada HUJUNG hari, sebelum anda balik. Dulang produk dilengkapkan, mesin dilap, pad dibersihkan, kain bersih sedia atas dulang. Apa-apa di bawah garisan stok minimum - ambil gambar dan laporkan malam ini.", "photo": "", "video": ""}]$q$::jsonb, $q$["Detailer", "PPF / Wrap Installer", "Tinted Installer", "QC Person", "Junior Technician", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-carwash$q$, $q$Car Wash$q$, $q$🫧$q$, 20, $q$Objective: clean, no water mark, no missed dirt. Every other service starts from here. Outside of the car only — interior is in Vacuum. (Handbook 4.1, 4.5)
Objektif: bersih, tiada kesan air, tiada kotoran tertinggal.$q$, $q$[{"text": "Two-staff method: Staff A pre-rinses and snow foams the whole car while Staff B starts the wheels at the same time, then joins A. Hand wash: A does the left side, B the right side.", "bm": "Kaedah dua orang: Staf A bilas awal dan sapu snow foam seluruh kereta, Staf B mula kerja rim pada masa yang sama, kemudian sertai A. Cuci tangan: A sebelah kiri, B sebelah kanan.", "photo": "", "video": "https://drive.google.com/drive/folders/1s83UphyQE8U_wB0SC5p8kltMNT6FYPvf"}, {"text": "PRE-RINSE, 2 to 3 minutes. Spray top to bottom. Focus on wheel arches and lower body — most of the dirt is there.", "bm": "BILAS AWAL, 2 hingga 3 minit. Semburan dari atas ke bawah. Fokus pada ruang tayar dan bahagian bawah badan - di situ kebanyakan kotoran.", "photo": "", "video": "https://drive.google.com/drive/folders/1oMDADGSO9Txd1T0d2o0kMd1IES4jK8Ev"}, {"text": "SNOW FOAM with Koch Chemie AF Active Foam. Cover the whole car evenly, wait 3 to 5 minutes. Do not let it dry on the surface.", "bm": "SNOW FOAM dengan AF Active Foam. Tutup seluruh kereta sekata, tunggu 3 hingga 5 minit. Jangan biarkan ia kering pada permukaan.", "photo": "", "video": "https://drive.google.com/drive/folders/1UqB2fTumVjbUTiVnvU8zf_CzDNxCiB59"}, {"text": "RIMS with Koch Chemie RRR for brake dust — rim face, inner barrel and brake dust area, not just the outside. Use the dedicated wheel bucket, never the body bucket.", "bm": "CUCIAN RIM dengan RRR untuk habuk brek. Muka rim, dalam rim, kawasan habuk brek. Bukan bahagian luar sahaja. Guna baldi rim yang khas. Jangan guna baldi badan kereta.", "photo": "", "video": "https://drive.google.com/drive/folders/18LmWuuG6ItY971_ITEmbxCfuyj8Vj8Nm"}, {"text": "Rim brush for the inner barrel and behind the spokes — this is the part people skip. Wool mitt (wheels only) for the rim face and the tyre. Clean all FOUR wheels.", "bm": "Berus rim untuk bahagian dalam dan belakang jejari. Inilah bahagian yang orang selalu tinggalkan. Mitt bulu untuk muka rim dan tayar. Bersihkan keempat-empatnya.", "photo": "", "video": "https://drive.google.com/drive/folders/1wFgT7FLz8SxOu3PZJkeWBVumE_77yFTz"}, {"text": "Never let RRR or any wheel chemical dry on the rim. Rinse before it dries, every time. Rims stay ON the car for a normal wash — never remove a rim.", "bm": "Jangan sekali-kali biarkan RRR atau sebarang bahan kimia rim kering pada rim. Bilas sebelum ia kering, setiap kali. Untuk cucian biasa, rim TIDAK ditanggalkan. Bersihkan pada kereta.", "photo": "", "video": "https://drive.google.com/drive/folders/16eVplCQNV-ZdSJv9XhKyCEETSbSt_oTq"}, {"text": "HAND WASH, two-bucket method with grit guards — one wash bucket, one rinse bucket. Top to middle to bottom, straight lines, NEVER circles. Roof, glass, door upper, door lower last.", "bm": "CUCI TANGAN, kaedah dua baldi dengan grit guard - satu baldi cuci, satu baldi bilas. Atas ke tengah ke bawah, garis lurus, jangan sekali-kali bulatan. Bumbung, cermin, pintu atas, pintu bawah terakhir.", "photo": "", "video": "https://drive.google.com/drive/folders/190T2iGAYm4scLo29bN4E3Ae-Ihd9LyBJ"}, {"text": "Separate mitts for wheels and bodywork, never the same one. Rinse and wring the mitt between panels. A dropped mitt is a dead mitt — it goes in the wash, not back on the car.", "bm": "Mitt berasingan untuk rim dan badan kereta. Jangan guna yang sama. Bilas dan perah mitt dengan betul antara panel. Mitt yang jatuh ialah mitt yang mati - ia masuk ke basuhan, bukan kembali ke kereta.", "photo": "", "video": "https://drive.google.com/drive/folders/19lKqpIg51YNYi-rZY8ef2cujkzsTvFMm"}, {"text": "FINAL RINSE, top to bottom again. Sheet the water off rather than blasting it — it leaves fewer spots. No foam left anywhere.", "bm": "BILAS AKHIR, dari atas ke bawah sekali lagi. Biarkan air mengalir turun dan bukan disembur kuat - ia meninggalkan kurang kesan. Tiada buih tertinggal di mana-mana.", "photo": "", "video": "https://drive.google.com/drive/folders/1HjkiBhAjRKRlMWwqMtqlSW7KvNl8K5VN"}, {"text": "Decontamination (only when the car goes on to polish, coating, PPF or wrap): iron and tar first, then clay on a wet surface with shampoo lubricant. Never clay a dry panel.", "bm": "Nyahcemar dibuat apabila kereta akan diteruskan ke menggilap, salutan, PPF atau wrap. Besi dan tar dahulu, kemudian clay pada permukaan basah dengan penyembur syampu sebagai pelincir. Jangan sekali-kali clay pada panel kering.", "photo": "", "video": "https://drive.google.com/drive/folders/13ZQbM7msDQiBeeZQr32nE221C3HKwkbG"}, {"text": "DRY: air blower first, into every crevice — mirrors, trims, emblems, handles, grille.", "bm": "Penghembus angin dahulu, ke setiap celah - cermin sisi, trim, lambang, pemegang, gril.", "photo": "", "video": "https://drive.google.com/drive/folders/1DZ6G_kz-om1hISlIKsEZBHVwVzTOfwme"}, {"text": "Exterior body: BLUE long cloth, top to bottom — roof, bonnet, door panels. Never dry-wipe a dusty car.", "bm": "Badan luar: kain panjang BIRU, atas ke bawah. Bumbung, bonet, panel pintu. Jangan sekali-kali lap kereta berhabuk dalam keadaan kering.", "photo": "", "video": "https://drive.google.com/drive/folders/1Xt36S85nwydV38G-uTItGXQ5G8Q5aje4"}, {"text": "Glass: RED cloth, inside and out, with Koch Chemie GLA Glas Star. Wipe straight, never circular.", "bm": "Cermin: kain MERAH, dalam dan luar, dengan GLA Glas Star. Lap lurus, jangan sekali-kali membulat.", "photo": "", "video": "https://drive.google.com/drive/folders/1pOvawujyJjMWmPKnCXYKUaWwtffW6VSB"}, {"text": "Inner door: BROWN cloth — inner panel, door side, rubber area. Wheels: wheel cloth only.", "bm": "Pintu dalam: kain COKLAT. Panel dalam, tepi pintu, kawasan getah. Keringkan rim dengan kain rim sahaja.", "photo": "", "video": "https://drive.google.com/drive/folders/1UgKjAUD9bBiy3HyGajWA6-eVoQIzKOyl"}, {"text": "TYRES: scrub the tyre wall with the wool mitt until the brown bloom is gone, rinse and let it dry, then apply Active Star tyre dressing evenly. Wipe off any on the paint or rim immediately — no sling.", "bm": "Gosok dinding tayar dengan mitt bulu sehingga lapisan perang hilang. Bilas dan biarkan tayar kering sebelum menyapu dressing. Sapu Active Star tyre dressing sekata. Lap serta-merta jika terkena cat atau rim. Jangan sampai terpercik.", "photo": "", "video": "https://drive.google.com/drive/folders/1qQ2vO3PLt5e8chjheZuVDKZDr_XuwNTy"}, {"text": "TRIM: clean it first, then treat plastic trim with Koch Chemie TS Topstar. Apply evenly, wipe off the excess, keep it off the glass and the paint.", "bm": "Bersihkan trim dahulu. Trim plastik dirawat dengan Koch Chemie TS Topstar. Sapu sekata dan lap lebihannya. Jauhkan daripada cermin dan daripada cat.", "photo": "", "video": "https://drive.google.com/drive/folders/18mlP_qPrqL8e4D08ImQklH_cdtrtVdwp"}, {"text": "Final check: no water dripping from the side mirror, door handle or emblem. All four wheels clean, inner barrel included. Wheel cloths go to the wash separately.", "bm": "Semakan akhir: tiada air menitis dari cermin sisi, pemegang pintu atau lambang. Keempat-empat rim bersih, termasuk dalam rim. Kain rim dibasuh berasingan.", "photo": "", "video": "https://drive.google.com/drive/folders/1qeQlg-h1ZUaF3UA_D1H7px3phEeW4wMR"}]$q$::jsonb, $q$["Detailer", "QC Person", "Junior Technician", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-vacuum$q$, $q$Vacuum$q$, $q$🧹$q$, 30, $q$Interior detail, carpet shampoo and glass. A customer looks at the paint for five seconds and sits inside for an hour — the interior is what they judge the job by. (Handbook 5.1–5.3)
Pelanggan melihat cat selama lima saat dan duduk di dalam selama sejam.$q$, $q$[{"text": "Tray check before you open the door: vacuum with brush attachments, air blower, soft brush for vents, GREEN/PURPLE cloth (interior), RED cloth (glass), BROWN cloth (inner door & rubber), interior cleaner, GLA, LS, TS, and a basket for customer items.", "bm": "Semuanya diletak atas dulang sebelum anda buka pintu kereta: vakum dengan alat berus, penghembus angin, berus lembut untuk vent, kain HIJAU/UNGU, kain MERAH, kain COKLAT, pencuci dalaman, GLA, LS, TS, dan bakul untuk barang pelanggan.", "photo": "", "video": "https://drive.google.com/drive/folders/16jhn4luSjqAl6hOLL__S4xHoEHy_TEq8"}, {"text": "Customer items: PHOTOGRAPH everything before you move it, put it in a basket (not on the floor or another car). Anything valuable goes to reception. Never open a locked compartment.", "bm": "AMBIL GAMBAR semuanya sebelum anda alihkan. Letakkan barang dalam bakul, bukan di lantai dan bukan dalam kereta lain. Apa-apa yang berharga diserahkan kepada kaunter. Jangan sekali-kali buka petak yang berkunci.", "photo": "", "video": "https://drive.google.com/drive/folders/1-fmavA1P1g7UknPfQZbzFtXLblLkCdes"}, {"text": "Remove all carpet mats and shake them off OUTSIDE the car. Carpets go on the long carpet table, never on the ground.", "bm": "Tanggalkan semua karpet, kibas di LUAR kereta. Karpet diletak di atas meja karpet panjang, jangan sekali-kali di atas tanah.", "photo": "", "video": "https://drive.google.com/drive/folders/1yTFiEO59NYjM8QQxFAPVFN420uB1gfp_"}, {"text": "BLOW FIRST, then vacuum. Blowing after vacuuming puts the dust back on the clean panels.", "bm": "TIUP DAHULU, kemudian vakum. Meniup selepas vakum akan mengembalikan habuk ke panel yang sudah bersih.", "photo": "", "video": "https://drive.google.com/drive/folders/1j2vTHwzAWWR7_f3Alg9XAwpQMcUyQu4S"}, {"text": "Soft brush for the air vents — a vacuum nozzle alone will not lift dust out of a vent.", "bm": "Berus lembut untuk vent penghawa dingin. Muncung vakum sahaja tidak akan mengeluarkan habuk dari vent.", "photo": "", "video": "https://drive.google.com/drive/folders/10_bc23G9RuoDGk3gZax8Nlu351e9lTt_"}, {"text": "Under the seats and in the seat rails — where everyone forgets to look. Boot, including under the floor panel. Work front to rear.", "bm": "Bawah tempat duduk dan dalam rel tempat duduk - tempat semua orang lupa periksa. But, termasuk bawah panel lantai. Kerjakan dari hadapan ke belakang.", "photo": "", "video": "https://drive.google.com/drive/folders/18Hrb9EL3dqKDucZ5DTOV1OZFD4bGC2T4"}, {"text": "Wipe down with GREEN cloth + interior cleaner: dashboard, console, steering, gear, door handles, cup holders.", "bm": "Kain HIJAU + pencuci dalaman - dashboard, konsol, stereng, gear, pemegang pintu, tempat cawan.", "photo": "", "video": "https://drive.google.com/drive/folders/1kaf3sOnRDqBncojNdgWnpaq1AOlOBNYG"}, {"text": "NEVER spray cleaner directly onto a screen, a button or an infotainment panel. Spray the cloth first, then wipe. Avoid excess moisture near electronics.", "bm": "JANGAN sekali-kali sembur pencuci terus pada skrin, butang atau panel infotainment. Sembur pada kain dahulu, kemudian lap. Elakkan lembapan berlebihan berhampiran mana-mana elektronik.", "photo": "", "video": "https://drive.google.com/drive/folders/1vS2UvBozx8s1tNKEoKB8pmz5sXCCST6m"}, {"text": "Plastic panels: Koch Chemie TS Topstar — apply to the cloth, wipe evenly, buff off the excess. Nothing shiny and greasy: a dashboard should look clean, not wet.", "bm": "Panel plastik: Koch Chemie TS Topstar. Sapu pada kain, lap sekata, gosok lebihannya. Jangan berkilat dan berminyak. Dashboard patut nampak bersih, bukan basah.", "photo": "", "video": "https://drive.google.com/drive/folders/1Y5a1OstgCBEgt6XBEG0hlDpg5D5eSKNS"}, {"text": "Leather: Koch Chemie LS Leather Star. Clean first, then treat — never treat a dirty seat, it seals the dirt in.", "bm": "Kulit: Koch Chemie LS Leather Star. Bersihkan dahulu, kemudian rawat. Jangan sekali-kali rawat tempat duduk yang kotor - ia mengunci kotoran di dalam.", "photo": "", "video": "https://drive.google.com/drive/folders/1f_8j1Ba59clmg13nw7oQanyntPkUfNy4"}, {"text": "Glass: RED cloth and GLA Glas Star, inside AND outside. Straight passes, never circles. Lower the side windows slightly to do the top edge. Mirrors and the reverse camera lens too.", "bm": "Kain MERAH dan Koch Chemie GLA Glas Star. Dalam DAN luar. Lap dengan sapuan LURUS, jangan sekali-kali membulat. Turunkan tingkap sisi sedikit dan lap tepi atas. Cermin sisi, cermin dalam dan lensa kamera undur.", "photo": "", "video": "https://drive.google.com/drive/folders/1jh4CJC8vSptskNnzuVgOuqrxokXWvsjX"}, {"text": "Door shuts and rubbers: BROWN cloth for the inner door, frame, door jambs, sill plates and boot shut. Dry the rubbers so no water drips on the customer's shoe.", "bm": "Kain COKLAT untuk pintu dalam, bingkai dan kedap getah. Jamb pintu, plat ambang dan bahagian but. Keringkan getah supaya air tidak menitis ke kasut pelanggan.", "photo": "", "video": "https://drive.google.com/drive/folders/1cepk6vs3ahDfRmbo-WidzGkrNfWveKah"}, {"text": "Carpet & upholstery shampoo (when sold): vacuum thoroughly first, test colour fastness on a hidden area, apply Koch Chemie MZR evenly — do not soak — agitate with a brush, then extract each area more than once.", "bm": "Vakum dengan menyeluruh dahulu. Periksa ketahanan warna pada kawasan tersembunyi. Sapu Koch Chemie MZR sekata - jangan terlalu basah. Gosok dengan berus, kemudian ekstrak setiap kawasan lebih daripada sekali.", "photo": "", "video": "https://drive.google.com/drive/folders/19GunQi2SvZKDAPv4xWg3pj-zgszTGPCl"}, {"text": "The job is not finished when it is clean — it is finished when it is DRY. Carpets dry on the carpet table; check the underside; press a dry cloth into the seat — if it comes up damp, it is not dry.", "bm": "Kerja ini tidak selesai apabila ia bersih. Ia selesai apabila ia KERING. Karpet dikeringkan di atas meja karpet. Periksa bahagian bawah karpet. Tekan kain kering pada tempat duduk - jika ia menjadi lembap, ia belum kering.", "photo": "", "video": "https://drive.google.com/drive/folders/1xRWe9NsjIH9zgmJN6BZxX9rd53FEA4XC"}, {"text": "Final check: PURPLE cloth for a last pass over water spots. Sit in the driver's seat and look around as a customer would. Carpets back the right way round, customer items back matching the photo.", "bm": "Kain UNGU untuk sapuan terakhir pada kesan air. Duduk di tempat duduk pemandu dan lihat sekeliling seperti pelanggan. Karpet dipasang semula dengan betul, barang pelanggan dipulangkan sepadan dengan gambar.", "photo": "", "video": "https://drive.google.com/drive/folders/1RoBvx6qumXsOypV-qfgZhBxLizBFuV7w"}, {"text": "No cloth, bottle, brush or rubbish left anywhere — check the boot and under the seats. Then call the department head for the 1st QC.", "bm": "Tiada kain, botol, berus atau sampah tertinggal di mana-mana dalam kereta. Periksa but dan bawah tempat duduk. Kemudian panggil ketua jabatan untuk QC pertama.", "photo": "", "video": "https://drive.google.com/drive/folders/1rhkeqPQRogVDKPRpG-BvCj73rEiNeGgx"}]$q$::jsonb, $q$["Detailer", "QC Person", "Junior Technician", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-polish$q$, $q$Polish$q$, $q$✨$q$, 40, $q$Polish = Check → Protect → Correct → Check again. Clear coat is about 50 microns thick; polishing removes 1 to 2 microns per session — that is why there is a limit. (Handbook 4.2)
Gilap = Periksa → Lindungi → Betulkan → Periksa semula.$q$, $q$[{"text": "Wash and decontamination complete AND PASSED. The car must be clean and dry before any polish, even 1 step.", "bm": "Cucian dan nyahcemar selesai DAN LULUS. Kereta mesti bersih dan kering sebelum sebarang gilap, walaupun 1 step.", "photo": "", "video": "https://drive.google.com/drive/folders/14TebmBbQH3XCGOb6nGHfREm1TQEj4eRh"}, {"text": "Check the car condition — scratches, watermarks, paint condition. Photograph any damage and tell the person in charge.", "bm": "Periksa keadaan kereta - calar, kesan air, keadaan cat. Ambil gambar sebarang kerosakan dan beritahu orang yang bertanggungjawab.", "photo": "", "video": "https://drive.google.com/drive/folders/1lnC4XOYqsoC_a5xL317Bpx8UAJG1Sm-4"}, {"text": "Do a test spot first to find the right combination before you correct the whole car.", "bm": "Buat ujian pada satu bahagian kecil dahulu untuk cari gabungan yang betul sebelum membetulkan seluruh kereta.", "photo": "", "video": "https://drive.google.com/drive/folders/1ESw9iykNgKkF24JUqoRYINLHMaqDT4B-"}, {"text": "Mask rubber, plastic, chrome and door handles.", "bm": "Tutup getah, plastik, krom dan pemegang pintu dengan pita.", "photo": "", "video": "https://drive.google.com/drive/folders/1puFm0WFA2joyqaYz7bumeRWP3JUYW-Vu"}, {"text": "Choose the level: 1 step = fine cut foam + Rupes Uno Advanced (gloss only, cannot remove scratches). 3 step = heavy cut foam + Koch Chemie M3.02 (minor scratches, light watermark).", "bm": "1 step = fine cut foam + Rupes Uno Advanced (kilat sahaja, tidak boleh hilangkan calar). 3 step = heavy cut foam + Koch Chemie M3.02 (calar halus, kesan air ringan).", "photo": "", "video": "https://drive.google.com/drive/folders/1z-WsvWC18inIksU6IOzR_uhVv-bIqTbE"}, {"text": "5 step = heavy cut foam or short wool with Koch Chemie H9.01, then fine cut foam with P6.01 finish (heavy watermark and scratches, 85 to 95%). Multi step = sandpaper — expert only.", "bm": "5 step = heavy cut foam atau short wool dengan Koch Chemie H9.01, kemudian fine cut foam dengan P6.01 (kesan air berat dan calar, 85 hingga 95%). Multi step = kertas pasir - pakar sahaja.", "photo": "", "video": "https://drive.google.com/drive/folders/1r9pmG7X8E0yBoYp3MG7QNPxvywXiFI1F"}, {"text": "Who may do what: 1 step all staff · 3 step trained staff · 5 step senior staff only · Multi step (sandpaper) SENIOR TECHNICIAN ONLY and manager approval before it starts.", "bm": "1 step semua kakitangan · 3 step kakitangan terlatih · 5 step kakitangan kanan sahaja · Multi step (mengamplas) juruteknik kanan SAHAJA, DAN kelulusan pengurus sebelum ia bermula.", "photo": "", "video": "https://drive.google.com/drive/folders/1o11oBLL7KN1VEFCrmoj14ApIVC3eY6bx"}, {"text": "Machine: DA (dual action) is the default for ALL polishing. Rotary is for experienced staff only. If you are not sure which machine to use, use the DA. When in doubt, start with the least aggressive pad.", "bm": "DA ialah pilihan utama untuk SEMUA gilap. Rotary untuk kakitangan berpengalaman sahaja. Jika anda tidak pasti mesin mana hendak digunakan, guna DA. Jika ragu-ragu, mula dengan pad yang paling lembut.", "photo": "", "video": "https://drive.google.com/drive/folders/1xVaX2s_3G-8QIdpTXKXtLxnkHF4tZwXj"}, {"text": "Work by section, 2ft x 2ft only.", "bm": "Kerjakan mengikut bahagian, 2 kaki x 2 kaki sahaja.", "photo": "", "video": "https://drive.google.com/drive/folders/1RF6XXLsrB2zJRGJHPlUWgXeaQ6tZocTt"}, {"text": "Keep the pad flat. Cross hatch — left to right, then up and down.", "bm": "Pastikan pad rata. Cross hatch - kiri ke kanan, kemudian atas ke bawah.", "photo": "", "video": "https://drive.google.com/drive/folders/1wo67lggf-Tiu4JagAPzfXobWPqRkC1rQ"}, {"text": "Medium pressure. Too hard burns the paint, too soft has no effect. Let the compound and the machine do the work.", "bm": "Tekanan sederhana. Terlalu kuat membakar cat, terlalu lembut tiada kesan. Biarkan kompaun dan mesin yang bekerja.", "photo": "", "video": "https://drive.google.com/drive/folders/15pQWDutNe83kGSv3fQHbNFslqelqvvxe"}, {"text": "Change pads often. Clean them with compressed air or a pad brush — a clogged pad stops cutting and starts smearing. Separate pads for cutting and for finishing.", "bm": "Tukar pad kerap. Bersihkan dengan angin termampat atau berus pad - pad tersumbat berhenti memotong dan mula mengotorkan. Guna pad berasingan untuk memotong dan untuk menyiapkan.", "photo": "", "video": "https://drive.google.com/drive/folders/1xMIjtElHcV833xCu0E8xw0RCiJpZ00-X"}, {"text": "Watch the paint temperature, especially on soft clear coats.", "bm": "Perhatikan suhu cat, terutamanya pada lapisan jernih yang lembut.", "photo": "", "video": "https://drive.google.com/drive/folders/1y8PWH6oAHuE5x29zvgAGlmocCfCD8cVD"}, {"text": "Wipe with clean microfiber and check under the detailing light. Repeat only within the safe limit.", "bm": "Lap dengan mikrofiber bersih dan periksa di bawah lampu detailing. Ulang hanya dalam had yang selamat.", "photo": "", "video": "https://drive.google.com/drive/folders/1FKRFfWk3hEnQ0n9F4CFWiUM2HlXRqUKV"}, {"text": "If a scratch can be felt with a fingernail, polishing will not remove it. Never promise 100% defect removal — 85 to 95% depending on condition.", "bm": "Jika calar boleh dirasa dengan kuku, menggilap tidak akan menghilangkannya. Jangan sekali-kali janjikan 100 peratus penghapusan kecacatan. 85 hingga 95 peratus bergantung pada keadaan.", "photo": "", "video": "https://drive.google.com/drive/folders/1Usspsdd_tLJ2qQdNFAvsD--vU8_HKM1p"}, {"text": "Before QC: no swirl marks, no heavy watermark, gloss even. No burn mark, no edge damage, no plastic stain. Trims and glass clean of polish residue. No masking tape left on the car.", "bm": "Tiada kesan pusaran, tiada kesan air berat, kilatan sekata. Tiada kesan terbakar, tiada kerosakan tepi, tiada kesan pada plastik. Trim dan cermin bersih daripada sisa bahan gilap. Tiada pita penutup tertinggal pada kereta.", "photo": "", "video": "https://drive.google.com/drive/folders/1lsulZ3L1dufdhUf8PyXm3MxgtnsFqAcs"}]$q$::jsonb, $q$["Detailer", "QC Person", "Junior Technician", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-coating$q$, $q$Coating$q$, $q$🛡️$q$, 50, $q$Coating is the last thing to go on the paint and it locks in whatever is underneath — swirls under a coating stay there for its whole life. Different coating means a different process. Do not mix, do not guess. (Handbook 4.3)
Salutan berbeza bermakna proses berbeza. Jangan campur, jangan teka.$q$, $q$[{"text": "Wash, vacuum and polish must ALL be complete and passed.", "bm": "Cucian, vakum dan menggilap mesti SEMUA selesai dan lulus.", "photo": "", "video": "https://drive.google.com/drive/folders/1X3KY6aF8yRP36HnJhnzMi7oCQbKH_3Ko"}, {"text": "Wipe every surface with Koch Chemie PPS panel preparation spray. No oil, no dust. PPS replaces IPA. Skip the panel wipe and the coating WILL fail — this is the most important step.", "bm": "Lap setiap permukaan dengan Koch Chemie PPS panel preparation spray. Tiada minyak, tiada habuk. PPS menggantikan IPA. Langkau lap panel dan salutan PASTI gagal. Ini langkah paling penting.", "photo": "", "video": "https://drive.google.com/drive/folders/1YvO-Z4eWaThMU3U6cvY4VTZX0gyJXMaU"}, {"text": "Final inspection for scratches, watermarks and polish result. Photograph if needed.", "bm": "Pemeriksaan akhir untuk calar, kesan air dan hasil gilap. Ambil gambar jika perlu.", "photo": "", "video": "https://drive.google.com/drive/folders/1GDs3CR3-4Et7_Q2JI3lGnbSTlyHoAgoo"}, {"text": "Check the environment — no direct sunlight, no dust being blown around, door shut.", "bm": "Periksa persekitaran - tiada cahaya matahari terus, tiada habuk berterbangan, pintu ditutup.", "photo": "", "video": "https://drive.google.com/drive/folders/1IzH31dLGf-U4rr9Hgdox6Nz15L7xKDOO"}, {"text": "Work one panel, or half a panel, at a time. Never larger.", "bm": "Kerjakan satu panel, atau separuh panel, pada satu masa. Jangan lebih besar.", "photo": "", "video": "https://drive.google.com/drive/folders/1kLQ4Iw1qPn7q91buPXLkTXIgQE155WAW"}, {"text": "Cancoat, Cancoat Pro, Mohs and C0.02: apply to the COATING CLOTH, then wipe evenly onto the panel. CANCOAT IS NOT SPRAYED ON THE CAR.", "bm": "Cancoat, Cancoat Pro, Mohs dan C0.02: sapu pada KAIN SALUTAN, kemudian lap sekata ke atas panel. CANCOAT TIDAK DISEMBUR PADA KERETA.", "photo": "", "video": "https://drive.google.com/drive/folders/1qgu4FHyYTJniein2xByRn7iQ_t2DLRpY"}, {"text": "Infinite (the only two-layer product): apply to the applicator block, cross hatch left-right then up-down. Confirm the base layer is right, then repeat for the top coat.", "bm": "Infinite: sapu pada blok aplikator, cross hatch kiri-kanan kemudian atas-bawah. Pastikan lapisan asas betul, kemudian ulang untuk lapisan atas.", "photo": "", "video": "https://drive.google.com/drive/folders/1NbX2XSM1MXPxp3bKJpFFUPoMHT6FtEQX"}, {"text": "Wait the flash time — a few seconds, depending on conditions.", "bm": "Tunggu flash time - beberapa saat, bergantung pada keadaan.", "photo": "", "video": "https://drive.google.com/drive/folders/18zMPb34vt7Xn_HW6GMPHReiEVKuKEPj8"}, {"text": "Level with microfiber. No streaks, no high spots. Wipe evenly.", "bm": "Ratakan dengan mikrofiber. Tiada calit, tiada tompok tinggi. Lap sekata.", "photo": "", "video": "https://drive.google.com/drive/folders/1BeJ1kHFPO-op_vUPabtAWLYWC0TwW4t7"}, {"text": "Check with light from an angle. Confirm no uneven reflection.", "bm": "Periksa dengan cahaya dari sudut. Pastikan tiada pantulan tidak sekata.", "photo": "", "video": "https://drive.google.com/drive/folders/1FY3P4-aC_g0WlF2ZJDndzkzFt7jV69k_"}, {"text": "Maintenance interval: Cancoat every 2 months · Cancoat Pro every 3 months · Mohs and C0.02 every 4 months · Infinite every 6 months. The interval is what the durability depends on.", "bm": "Cancoat setiap 2 bulan · Cancoat Pro setiap 3 bulan · Mohs dan C0.02 setiap 4 bulan · Infinite setiap 6 bulan. Tempoh ini yang menentukan ketahanannya.", "photo": "", "video": "https://drive.google.com/drive/folders/1NHEwgKvUU_y-R3q2jzgyNayt4mzIdbX6"}, {"text": "Wax: Koch Chemie PW Protector Wax with a soft foam applicator, spread evenly. Buff off with soft microfiber, STRAIGHT passes, never circles. No washing for 24 hours.", "bm": "Koch Chemie PW Protector Wax, sapu dengan aplikator span lembut, ratakan sekata. Gosok keluar dengan mikrofiber lembut. Sapuan LURUS, jangan sekali-kali membulat. Jangan basuh selama 24 jam.", "photo": "", "video": "https://drive.google.com/drive/folders/1KrjDeA_hN9s8yJ7Lqmma2lJv9XAxcU9d"}, {"text": "3 Step Hydro Bathe+: 1 Gyeon Bathe+ → 2 Gyeon WetCoat → 3 Koch Chemie PW Protector Wax, in this order. Missing one is not the service the customer paid for.", "bm": "1 Gyeon Bathe+ → 2 Gyeon WetCoat → 3 Koch Chemie PW Protector Wax, dalam urutan ini. Tertinggal satu bermakna itu bukan perkhidmatan yang pelanggan bayar.", "photo": "", "video": "https://drive.google.com/drive/folders/1atwMGjS1UNyN8FZzLKkGkscF3o39_l8n"}, {"text": "Coating maintenance visit: wash the car, then spray Koch Chemie S0.02 spray sealant. NO POLISH. Record the visit and set the next maintenance date.", "bm": "Cuci kereta, kemudian sembur Koch Chemie S0.02 spray sealant. JANGAN GILAP. Rekodkan lawatan dan tetapkan tarikh penjagaan seterusnya.", "photo": "", "video": "https://drive.google.com/drive/folders/1uV4cF4JX495L-FepO59Y2B7brH3d98vD"}, {"text": "Curing: no washing for 7 days, avoid water and dust. Fill in the maintenance card (first wash date and return visit) and hand the next date to reception.", "bm": "Jangan basuh selama 7 hari. Elakkan air dan habuk semasa pengeringan. Isi kad penjagaan - tarikh cucian pertama dan lawatan ulangan. Serahkan tarikh penjagaan seterusnya kepada kaunter.", "photo": "", "video": "https://drive.google.com/drive/folders/16ax9OjmLmfy-pU3HjvOYaJG0IlNwg-Nn"}, {"text": "Before QC: coating levelled — no streaks, no high spots, no haze, under the detailing lights. No coating residue on trims, rubber or glass.", "bm": "Salutan diratakan - tiada calit, tiada tompok tinggi, tiada kabur. Periksa di bawah lampu detailing. Tiada sisa salutan pada trim, getah atau cermin.", "photo": "", "video": "https://drive.google.com/drive/folders/1BRVPS6FyOI9kKTCNYNp8qtIuScixcu3s"}]$q$::jsonb, $q$["Detailer", "QC Person", "Junior Technician", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-ppf$q$, $q$PPF$q$, $q$🎞️$q$, 60, $q$PPF and wrap are one department, working in the clean bays. Film locks in whatever is underneath — any swirl or watermark stays there permanently under the film. (Handbook 4.4)
Filem mengunci apa sahaja yang ada di bawahnya.$q$, $q$[{"text": "Clean room: 15 to 32 degrees, never in direct sunlight. Door shut, floor damp mopped, nobody walking in and out.", "bm": "15 hingga 32 darjah. Jangan sekali-kali di bawah cahaya matahari terus. Pintu ditutup, lantai dimop lembap, tiada orang keluar masuk.", "photo": "", "video": "https://drive.google.com/drive/folders/10dg4Yqtc7u_3mCYlbyGJZrPYSfgYlPUj"}, {"text": "The clean room INSTALLS ONLY — every minute of prep done inside it is a wasted bay. The car must be completely dry before it enters.", "bm": "Bilik bersih untuk PEMASANGAN SAHAJA. Setiap minit penyediaan yang dibuat di dalamnya ialah bay yang terbazir. Kereta mesti kering sepenuhnya sebelum masuk.", "photo": "", "video": "https://drive.google.com/drive/folders/1bSWRqAxcu-cfCG8IDeRwnzwhay4covdB"}, {"text": "Outside the clean room: full wash and decontamination — iron, tar, clay.", "bm": "Cucian penuh dan nyahcemar: besi, tar, clay.", "photo": "", "video": "https://drive.google.com/drive/folders/1QMJWkWO0NZNRQG8pSkiRDfgpSzANMvte"}, {"text": "Degrease every panel and every edge with Koch Chemie PPS — door edges, seams, rubber lips, under handles. PPS replaces IPA on all film work. Do not use IPA.", "bm": "Nyahgris setiap panel dan setiap tepi dengan Koch Chemie PPS. Tepi pintu, sambungan, bibir getah, bawah pemegang. PPS menggantikan IPA untuk semua kerja filem. Jangan guna IPA.", "photo": "", "video": "https://drive.google.com/drive/folders/1lk_YlztDPI7vJNQ6maK84v4-qjTthMBc"}, {"text": "Remove badges, trim and handles where the job allows — this is what stops an exposed edge lifting later.", "bm": "Tanggalkan lambang, trim dan pemegang jika kerja itu membenarkan. Inilah yang menghalang tepi terdedah daripada terangkat kemudian.", "photo": "", "video": "https://drive.google.com/drive/folders/17k03FxVqTD9wV55W25o-hmZZvprJgA5u"}, {"text": "Photograph the paint condition and show the customer anything found BEFORE the film goes on.", "bm": "Ambil gambar keadaan cat dan tunjukkan kepada pelanggan apa-apa yang dijumpai SEBELUM filem dipasang.", "photo": "", "video": "https://drive.google.com/drive/folders/1f7SfI-_pfv8WvXZPz6JlXzTk9r9gbpxn"}, {"text": "Cut the plotter pattern. Record roll number, pattern metres and actual metres on the material sheet.", "bm": "Potong corak plotter. Rekodkan nombor gulungan, meter corak dan meter sebenar pada helaian bahan.", "photo": "", "video": "https://drive.google.com/drive/folders/138ZkB3qSa57L5I5C4lBWp8maJqrs2F8j"}, {"text": "Mix slip solution in the pressure tank: 20% gel to 80% water.", "bm": "Campurkan larutan slip dalam tangki tekanan: 20% gel kepada 80% air.", "photo": "", "video": "https://drive.google.com/drive/folders/1BxuYPYEFT62Tu9_fpEbjnvhZlk3OJQTY"}, {"text": "Wet your hands and the panel. Position the film, anchor with one squeegee pass down the centre.", "bm": "Basahkan tangan anda dan panel. Letakkan filem, lekatkan dengan satu sapuan squeegee di tengah.", "photo": "", "video": "https://drive.google.com/drive/folders/1H8v_SYt3baVoJlv_qcATRFkRs-NcCsDi"}, {"text": "Work from the centre outwards with overlapping passes, pushing solution and air to the edge.", "bm": "Kerjakan dari tengah ke luar dengan sapuan bertindih, menolak larutan dan udara ke tepi.", "photo": "", "video": "https://drive.google.com/drive/folders/11udPKOMwXG9zM8a5xnBdYXdcus530T74"}, {"text": "WRAP EVERY EDGE. An unwrapped edge lifts within weeks — it is the most common reason a customer comes back.", "bm": "BALUT SETIAP TEPI. Tepi yang tidak dibalut akan terangkat dalam beberapa minggu - sebab paling kerap pelanggan datang semula.", "photo": "", "video": "https://drive.google.com/drive/folders/1vklZNkB5U863vXSUCqx33VtF4LbmUR5m"}, {"text": "Heat gun for curves and wrapped edges. Short passes, keep moving. Use knifeless tape for cuts — never a blade on paint.", "bm": "Heat gun untuk lengkungan dan tepi yang dibalut. Sapuan pendek, terus bergerak. Guna knifeless tape untuk potongan - jangan sekali-kali bilah pada cat.", "photo": "", "video": "https://drive.google.com/drive/folders/1NH5B3OGyOEfFzIxV1zb9E6G6DJDq6PzR"}, {"text": "Self inspect under strong light, then call the department head for the 1st QC.", "bm": "Periksa sendiri di bawah cahaya kuat, kemudian panggil ketua jabatan untuk QC pertama.", "photo": "", "video": "https://drive.google.com/drive/folders/1ax3Nv8taYttEoncvhfqhD2Ced8sUzEGf"}, {"text": "Rest for the specified time before the car moves. Tell the customer the first wash date.", "bm": "Rehatkan untuk tempoh yang ditetapkan sebelum kereta digerakkan. Beritahu pelanggan tarikh cucian pertama.", "photo": "", "video": "https://drive.google.com/drive/folders/1j_hCv4A_AiGvRL1yb9yNw0jgosWwZppm"}, {"text": "Touch-up or amendment: ALWAYS APPLY SOAP FIRST — without soap you will pull the paint off with the film. Log every touch-up on the spot, with the real reason.", "bm": "SENTIASA SAPU SABUN DAHULU sebelum sebarang pembaikan atau pindaan. Tanpa sabun anda akan menarik cat terkelupas bersama filem. Rekodkan setiap pembaikan serta-merta, dengan sebab yang sebenar.", "photo": "", "video": "https://drive.google.com/drive/folders/16B88L5TAi5X-lPhqjrkQXoKzFonsygQN"}, {"text": "Production target: Day 1 — 1 full body PPF, OR 2 to 3 full front PPF. Day 2 — QC and touch-up. Day 3 — deliver the car.", "bm": "Hari 1 - 1 PPF badan penuh, ATAU 2 hingga 3 PPF depan penuh. Hari 2 - QC dan pembaikan. Hari 3 - serahkan kereta.", "photo": "", "video": "https://drive.google.com/drive/folders/1Pm0LqNdex3qWd3ybjE8NZV6v9wU8nvbX"}, {"text": "Every roll used goes on the material sheet. Nobody is fined for spoiled film — hiding it is the only offence.", "bm": "Setiap gulungan yang digunakan direkod pada helaian bahan. Tiada sesiapa didenda kerana filem rosak. Menyembunyikannya sahaja yang menjadi kesalahan.", "photo": "", "video": "https://drive.google.com/drive/folders/1OJc5y9TCZY_DbrJMta3IiqzPzT4bypkH"}, {"text": "QC looks for: bubbles, dust specks, edge lifting, unwrapped edges, alignment, stretch marks, knife marks — under the detailing lights, never daylight or torch.", "bm": "Cari: gelembung, habuk, tepi terangkat, tepi tidak dibalut, penjajaran, kesan regangan, kesan pisau. Periksa di bawah lampu detailing, jangan guna cahaya siang atau lampu suluh.", "photo": "", "video": "https://drive.google.com/drive/folders/16oxV9qt24r7181kqSTnqCgQLSem9_TcY"}]$q$::jsonb, $q$["PPF / Wrap Installer", "QC Person", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-wrapping$q$, $q$Wrapping$q$, $q$🎨$q$, 70, $q$Wrap changes the colour and is NOT self-healing. Vinyl is thinner and less forgiving than PPF, and shows every imperfection underneath. (Handbook 4.4 F–H)
Wrap menukar warna dan BUKAN pulih sendiri.$q$, $q$[{"text": "Before accepting the job, check the paint. Peeling clear coat, rust, or paint under 30 days old will lift the vinyl.", "bm": "Periksa cat. Lapisan jernih terkelupas, karat, atau cat kurang 30 hari akan menyebabkan vinil terangkat.", "photo": "", "video": "https://drive.google.com/drive/folders/1QYCKv6ZjMSpe2Mi9B-AUX76sOCYkourG"}, {"text": "Tell the customer BEFORE you accept the job, not after.", "bm": "Beritahu pelanggan SEBELUM anda terima kerja itu, bukan selepas.", "photo": "", "video": "https://drive.google.com/drive/folders/1f6yOc-ITzbwFEsbp4R7usfn-iA98QfSY"}, {"text": "Full wash and decontamination. Any grit left under vinyl becomes a visible bump.", "bm": "Cucian penuh dan nyahcemar. Sebarang pasir yang tertinggal di bawah vinil akan menjadi bonjol yang kelihatan.", "photo": "", "video": "https://drive.google.com/drive/folders/1VCVf5VuujRA_Eqa_p9w_t4JCei4lWpPl"}, {"text": "Degrease with PPS, then degrease again at the edges and inside the door jambs.", "bm": "Nyahgris dengan PPS, kemudian nyahgris sekali lagi pada tepi dan di dalam jamb pintu.", "photo": "", "video": "https://drive.google.com/drive/folders/19TUaqTxzpe0n9-VQJGzJnuwATkLwmy3O"}, {"text": "Remove badges, handles, lights and trim wherever possible.", "bm": "Tanggalkan lambang, pemegang, lampu dan trim di mana boleh.", "photo": "", "video": "https://drive.google.com/drive/folders/1HXDBZTCc-khDyXSYamQzQGlhSY9CzfkA"}, {"text": "Work panel by panel. Position with TENSION, not stretch.", "bm": "Kerjakan panel demi panel. Letakkan dengan TEGANGAN, bukan regangan.", "photo": "", "video": "https://drive.google.com/drive/folders/1Q3hFt_v5NaUAVsGygAQsaHYIyBxONGtk"}, {"text": "Squeegee from the centre outwards with a felt edge so the vinyl is not scratched.", "bm": "Squeegee dari tengah ke luar dengan tepi felt supaya vinil tidak tercalar.", "photo": "", "video": "https://drive.google.com/drive/folders/18hBRSDFU-1m0BDPgmXLnbrxcDWfVPC10"}, {"text": "For curves, warm the vinyl gently and let it relax into shape. Do not pull it cold.", "bm": "Untuk lengkungan, panaskan vinil perlahan dan biarkan ia melentur. Jangan tarik sejuk.", "photo": "", "video": "https://drive.google.com/drive/folders/1_kdsiwKXvCwQmXHkeISLKJf76qwkjfcS"}, {"text": "Wrap every edge and tuck it into panel gaps and behind removed parts.", "bm": "Balut setiap tepi dan selitkan ke dalam celah panel dan di belakang bahagian yang ditanggalkan.", "photo": "", "video": "https://drive.google.com/drive/folders/11X1COwGnAzKZtEcq-VyYNB6Y0plS8uoD"}, {"text": "POST HEAT every stretched area and every recess to the film specification. Skipping post heat is the most common cause of a wrap failing.", "bm": "PANASKAN SEMULA setiap kawasan yang diregang dan setiap lekuk mengikut spesifikasi filem. Melangkau pemanasan semula ialah punca paling kerap wrap gagal.", "photo": "", "video": "https://drive.google.com/drive/folders/1jlbq1YUUCyWOyY0djubBGPKLH49l_J7X"}, {"text": "Plan seams along a body line, overlapping the way water runs off.", "bm": "Rancang sambungan mengikut garisan badan, bertindih mengikut arah air mengalir.", "photo": "", "video": "https://drive.google.com/drive/folders/1VlGXShn2AHQmHKPwH6-_VM-flfTn0Wnq"}, {"text": "Use knifeless tape for cuts on the panel. A blade on paint is a scratch you pay for.", "bm": "Guna knifeless tape untuk potongan pada panel. Bilah pada cat ialah calar yang anda bayar.", "photo": "", "video": "https://drive.google.com/drive/folders/1JBhnOy2__3KS8u9jkiUZqOhnRRm7wAev"}, {"text": "Self inspect under strong light, then call the department head for the 1st QC.", "bm": "Periksa sendiri di bawah cahaya kuat, kemudian panggil ketua jabatan untuk QC pertama.", "photo": "", "video": "https://drive.google.com/drive/folders/1lWGEaoo5qgNncWlyZ6KFHpiUxuLjM4s1"}, {"text": "Aftercare to tell the customer: hand wash only, no automatic car wash brushes, no pressure washer close to the edges, no wax containing solvents.", "bm": "Cuci tangan sahaja. Tiada berus cucian kereta automatik. Tiada jet tekanan dekat dengan tepi. Tiada wax yang mengandungi pelarut.", "photo": "", "video": "https://drive.google.com/drive/folders/18SPFnsSQPYKtxf7s3dTD5MuHa6Tp3Zdo"}]$q$::jsonb, $q$["PPF / Wrap Installer", "QC Person", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-tinted$q$, $q$Tinted$q$, $q$🕶️$q$, 80, $q$Tint is its own department, working in the clean bays. Ninety percent of tint complaints start with dirty glass. (Handbook 4.4 I–L)
Sembilan puluh peratus aduan tinted bermula dengan cermin yang kotor.$q$, $q$[{"text": "Scrub the inside of the glass with solution and a white pad.", "bm": "Gosok bahagian dalam dengan larutan dan pad putih.", "photo": "", "video": "https://drive.google.com/drive/folders/1cJrBRRVqhHY4y7D4AupV_VFILvaimYkd"}, {"text": "Toothbrush the defroster plugs and the top edge where the glass meets the seal.", "bm": "Berus gigi pada palam defroster dan tepi atas di mana cermin bertemu kedap.", "photo": "", "video": "https://drive.google.com/drive/folders/1LxL7T2CHYJ5zUmwqLnrsINCpUwA5Xb22"}, {"text": "Squeegee, then wipe with a lint free towel.", "bm": "Squeegee, kemudian lap dengan tuala bebas serat.", "photo": "", "video": "https://drive.google.com/drive/folders/1qD-cXON3ox8sm6LRX1R0nIHdoxRfN6Bt"}, {"text": "Check the glass for chips and scratches BEFORE you start. They show through the film.", "bm": "Periksa cermin untuk serpihan dan calar SEBELUM anda mula. Ia akan kelihatan menembusi filem.", "photo": "", "video": "https://drive.google.com/drive/folders/1C1iModjtE0cj8N3ywMRq2yWlZ7wT-5aW"}, {"text": "Rear screen heat shrink: lay the film liner up on the OUTSIDE of the glass, spray, and squeegee a horizontal anchor.", "bm": "Letakkan filem dengan liner menghadap atas di LUAR cermin, sembur, dan squeegee sebagai pengikat mendatar.", "photo": "", "video": "https://drive.google.com/drive/folders/1IPD1n8jpxvgjVUnB5H5gXs0twg3AuXF_"}, {"text": "The excess gathers into fingers at the top and bottom. Fingers must be at the top and bottom — film cannot be shrunk horizontally.", "bm": "Lebihan akan berkumpul menjadi jari di bahagian atas dan bawah. Filem tidak boleh dikecutkan secara mendatar.", "photo": "", "video": "https://drive.google.com/drive/folders/1bJO9ES_FPwC6AnBrf_eHZbRdqoOPKnDa"}, {"text": "Pass the heat gun quickly over one finger until the film reacts, then flatten it. Work along the rest, then repeat with a hard card.", "bm": "Lalukan heat gun dengan cepat pada satu jari sehingga filem bertindak balas, kemudian ratakan. Teruskan pada yang lain, kemudian ulang dengan kad keras.", "photo": "", "video": "https://drive.google.com/drive/folders/1J1k4OZWM8hS2JsdeN9xFQlIAAFGmK9o8"}, {"text": "Keep heat away from the film edge or it burns and curls.", "bm": "Jauhkan haba dari tepi filem atau ia akan terbakar dan melengkung.", "photo": "", "video": "https://drive.google.com/drive/folders/1KKJQHl8sU0pXcpzK46LrqOei10hkBXhn"}, {"text": "Final cut 3 to 4mm outside the dot matrix. New blade every time.", "bm": "Potongan akhir 3 hingga 4mm di luar dot matrix. Bilah baharu setiap kali.", "photo": "", "video": "https://drive.google.com/drive/folders/14ASChhITRdBdyNPcJOeaMu3fj0ZzTkkm"}, {"text": "Peel the liner keeping the adhesive wet, spray the glass heavily, position the film.", "bm": "Tanggalkan liner sambil memastikan pelekat kekal basah, sembur cermin dengan banyak, letakkan filem.", "photo": "", "video": "https://drive.google.com/drive/folders/1YxSo8OrbDSfodURyWduQYelNQ75ifJ5u"}, {"text": "Squeegee from the centre outwards, then work every edge with a hard card.", "bm": "Squeegee dari tengah ke luar, kemudian kerjakan setiap tepi dengan kad keras.", "photo": "", "video": "https://drive.google.com/drive/folders/1SXYrrxUmkTShVPxNftAw0ohsWGa3I8ne"}, {"text": "Side windows: lower slightly, do the top edge first, then raise and finish.", "bm": "Tingkap sisi: turunkan sedikit, buat tepi atas dahulu, kemudian naikkan dan siapkan.", "photo": "", "video": "https://drive.google.com/drive/folders/1ytE2HdAEHvykpeWvCt6UkuxQVaRXOisO"}, {"text": "Self inspect, then call the department head for the 1st QC.", "bm": "Periksa sendiri, kemudian panggil ketua jabatan untuk QC pertama.", "photo": "", "video": "https://drive.google.com/drive/folders/1m3sWM5Ak-iW2-6H4uhSutby2Oash1LpL"}, {"text": "Handover: curing is 3 to 5 days, windows stay UP. Slight haze, water pockets or small bubbles are normal while curing and will clear — tell the customer this AT handover.", "bm": "Pengeringan 3 hingga 5 hari. Tingkap kekal NAIK. Sedikit kabur, kantung air atau gelembung kecil adalah normal semasa pengeringan dan akan hilang. Beritahu pelanggan perkara ini SEMASA penyerahan.", "photo": "", "video": "https://drive.google.com/drive/folders/1xt7v-DakglDwBUJWadRg_YXIJavwt_fI"}]$q$::jsonb, $q$["Tinted Installer", "PPF / Wrap Installer", "QC Person", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-engine$q$, $q$Engine Bay$q$, $q$🔧$q$, 82, $q$The only exterior job where water meets electrics — everything here is about keeping the two apart. Work on a COOL engine. (Handbook 4.6)
Satu-satunya kerja luar di mana air bertemu elektrik.$q$, $q$[{"text": "Engine OFF and COOL. If the car has just arrived and the engine is hot, leave it. Never spray a hot engine.", "bm": "Enjin MATI dan SEJUK. Jika kereta baru sampai dan enjin masih panas, biarkan dahulu.", "photo": "", "video": "https://drive.google.com/drive/folders/1BBOIGcwgu37B_b9EAXYGara5-uC0lHEH"}, {"text": "Open the bonnet and look first. Note any oil leak, loose wire or damaged cover and tell the SA BEFORE you start.", "bm": "Buka bonet dan lihat dahulu. Catat sebarang kebocoran minyak, wayar longgar atau penutup rosak dan beritahu SA SEBELUM anda mula.", "photo": "", "video": "https://drive.google.com/drive/folders/1Wlv__lHN5X2zWIFa_yOg_FlS6mV3_1iB"}, {"text": "Photograph the engine bay before you touch it.", "bm": "Ambil gambar ruang enjin sebelum anda menyentuhnya.", "photo": "", "video": "https://drive.google.com/drive/folders/1nRpv0YpuamJuiRSVVvxQAreSOqpc5CjQ"}, {"text": "COVER the battery and every open hole with cloth — air intake, alternator, fuse box, exposed connectors, any opening. Do not start until everything that must stay dry is covered.", "bm": "TUTUP bateri dan setiap lubang terbuka dengan kain. Salur masuk udara, alternator, kotak fius, penyambung terdedah, mana-mana bukaan. Jangan mula kerja sehingga semua yang mesti kekal kering telah ditutup.", "photo": "", "video": "https://drive.google.com/drive/folders/1PnjjgK_sqHbAmbyRcvwGnlOiSTLxlmL-"}, {"text": "Apply Koch Chemie GS Green Star and agitate with a SOFT BRUSH — corners, cover edges and seams.", "bm": "Sapu Koch Chemie GS Green Star dan gosok dengan BERUS LEMBUT. Kerjakan ke sudut, tepi penutup dan sambungan.", "photo": "", "video": "https://drive.google.com/drive/folders/1Iz_5DtKGv6SnI1JmzsrpCBX_UMMjaxaC"}, {"text": "Do not blast water into the bay — use as little water as will do the job, away from the covered areas. Rinse gently. Never let GS dry on a surface.", "bm": "Jangan sembur air dengan kuat ke dalam ruang enjin. Guna air sesedikit mungkin, jauhkan dari kawasan yang ditutup. Bilas perlahan dan sekata. Jangan sekali-kali biarkan GS kering pada permukaan.", "photo": "", "video": "https://drive.google.com/drive/folders/11uh0oKsb-1ineeCNHFmIVtBd6UD-lI5X"}, {"text": "BLOW THE WATER OFF FIRST. Start with the WIRING AREA — every connector, loom and plug. Then covers, seams, corners and the bonnet underside.", "bm": "TIUP AIR KELUAR DAHULU. Mulakan dengan KAWASAN PENDAWAIAN. Setiap penyambung, setiap gegelung wayar, setiap palam. Kemudian penutup, sambungan, sudut, bahagian bawah bonet.", "photo": "", "video": "https://drive.google.com/drive/folders/1yCzW2XYQqc0ZCgcI5nr-n8iU9N36tRar"}, {"text": "Remove the cloths only after the surrounding area is dry. Check under and behind the covers.", "bm": "Tanggalkan kain hanya selepas kawasan sekelilingnya kering. Periksa bawah dan belakang penutup.", "photo": "", "video": "https://drive.google.com/drive/folders/1NAj7kMigYSj5DIj6zOc03ni_Ytk75Aty"}, {"text": "Before starting the engine: all cloths removed and COUNTED — the number that went in is the number that comes out. No brush, bottle or cloth left in the bay.", "bm": "Semua kain ditanggalkan. Kira - bilangan yang masuk ialah bilangan yang keluar. Tiada berus, tiada botol, tiada kain tertinggal.", "photo": "", "video": "https://drive.google.com/drive/folders/167h9WNT9ZEjQbcP31cxI7x5VFIfG0Tuu"}, {"text": "Start the engine and listen. Any warning light, rough running or new noise — stop and tell the manager immediately. Let it run briefly so moisture evaporates.", "bm": "Hidupkan enjin dan dengar. Sebarang lampu amaran, enjin tidak lancar, atau bunyi baharu - berhenti dan beritahu pengurus serta-merta. Biarkan ia hidup seketika supaya lembapan menyejat.", "photo": "", "video": "https://drive.google.com/drive/folders/1qUJya2ZuVBUQ31k7wriId5kkUn00d38n"}, {"text": "Before and after photos recorded. Then call the department head for the 1st QC.", "bm": "Gambar sebelum dan selepas direkodkan. Kemudian panggil ketua jabatan untuk QC pertama.", "photo": "", "video": "https://drive.google.com/drive/folders/1WobHtsrwuXtHVbs1MY2UptAPXdt4kIvr"}]$q$::jsonb, $q$["Detailer", "QC Person", "Junior Technician", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-rimsbay$q$, $q$Rims Bay$q$, $q$🛞$q$, 84, $q$A separate paid service and the ONLY job where rims come off. A mistake here is a SAFETY problem — a wheel not torqued correctly can come loose on the road. Removing and refitting is SENIOR ONLY. (Handbook 4.7)
Menanggalkan dan memasang semula rim adalah SENIOR SAHAJA.$q$, $q$[{"text": "Drive the car to the LIFTER BAY only. Lift on the car's jack points — never on a sill, floor pan or plastic cover. Check the car is stable before anyone puts a hand near a wheel.", "bm": "Pandu kereta ke LIFTER BAY sahaja. Gunakan titik jack. Jangan sekali-kali angkat pada sill, lantai atau penutup plastik. Pastikan kereta stabil sebelum sesiapa meletakkan tangan dekat rim.", "photo": "", "video": "https://drive.google.com/drive/folders/1YJy0VgY3OvMpHQTEV0IMJcl6fGfm9oFw"}, {"text": "Our lifter is a SCISSOR LIFT — a low car will not clear it. If the car is too low, the rims are NOT removed; tell the SA. If unsure, ask the senior BEFORE you drive it on.", "bm": "Lifter kami ialah SCISSOR LIFT. Kereta rendah tidak akan lepas. Jika kereta terlalu rendah, rim TIDAK ditanggalkan. Beritahu SA. Jika tidak pasti, tanya senior SEBELUM anda pandu masuk.", "photo": "", "video": "https://drive.google.com/drive/folders/1pf9TXhRkG7OFZde7pk0CE2B7k3bVRr25"}, {"text": "Removing the rims: SENIOR ONLY. Keep each wheel's nuts with that wheel, lay rims face up on a protected surface, and count the wheels and nuts before you start.", "bm": "SENIOR SAHAJA. Simpan nat setiap rim bersama rim itu. Letakkan rim di atas permukaan yang dilindungi, menghadap atas. Kira bilangan rim dan nat sebelum anda mula.", "photo": "", "video": "https://drive.google.com/drive/folders/1MARRKJI9V8N5XKpXS2M7ov-ppQon_zLC"}, {"text": "Wash and brush the rims bay and mudguard with Koch Chemie GS Green Star — arch liner, back of the mudguard. Rinse before it dries.", "bm": "Cuci dan berus rims bay dan mudguard dengan Koch Chemie GS Green Star. Kerjakan ke dalam pelapik ruang tayar dan belakang mudguard. Bilas sebelum produk kering.", "photo": "", "video": "https://drive.google.com/drive/folders/1srvCPkBdhhFP2Opt_UBcelMw8PeCvAbi"}, {"text": "Wash the rims with RRR together with GS — face, inner barrel, brake dust area and back of the spokes. Rinse thoroughly, nothing left in the bolt holes. Dry completely.", "bm": "Cuci rim dengan Koch Chemie RRR bersama GS. Muka rim, dalam rim, kawasan habuk brek dan belakang jejari. Bilas dengan menyeluruh, tiada produk dalam lubang bolt. Keringkan rim sepenuhnya.", "photo": "", "video": "https://drive.google.com/drive/folders/1D0fCpXsVtQoJb1Xa0zD1j4rtwBrrTpVt"}, {"text": "Coat with Gyeon Q2 Cancoat on the COATING CLOTH (not sprayed): face, then spokes, then barrel. Level with microfiber.", "bm": "Sapu Gyeon Q2 Cancoat pada KAIN SALUTAN, kemudian lap sekata pada rim. Cancoat tidak disembur. Muka, kemudian jejari, kemudian dalam rim. Ratakan dengan mikrofiber.", "photo": "", "video": "https://drive.google.com/drive/folders/1hGeLDbasSRtA2As7QfUjJfKaZtj9pExN"}, {"text": "Infrared lamp for rims: 30 MINUTES. Set it and leave it — do not cut it short. Check under angled light before the rim goes back on.", "bm": "Lampu inframerah untuk rim: 30 MINIT. Jangan dipendekkan. Periksa di bawah cahaya dari sudut sebelum rim dipasang semula.", "photo": "", "video": "https://drive.google.com/drive/folders/1ejYHUq0BiTKw0xF_97ys7EIbC4ALSPsI"}, {"text": "Refitting: SENIOR ONLY, the same person who removed them. Each wheel gets its own nuts back. Use the TORQUE STICK — a rattle gun alone is not acceptable.", "bm": "SENIOR SAHAJA - orang yang sama yang menanggalkan rim yang memasangnya semula. Setiap rim mendapat natnya sendiri semula. Pasang menggunakan TORQUE STICK. Rattle gun sahaja tidak boleh diterima.", "photo": "", "video": "https://drive.google.com/drive/folders/1cgmf-RnK6MwRol8mVKZ1HfAMb3pe1k_1"}, {"text": "Torque 110 Nm to 150 Nm for the car — never guess, never above it. Tighten in a star pattern. Count the nuts on every wheel and check every wheel again before the car comes off the lifter.", "bm": "Torque 110 Nm hingga 150 Nm. Jangan teka, jangan melebihi. Ketatkan mengikut corak bintang. Kira nat pada setiap rim dan periksa semula setiap rim sebelum kereta diturunkan dari lifter.", "photo": "", "video": "https://drive.google.com/drive/folders/1QKdIpKgKJpaaWLkj2R_F1TxEpGKuyh2Y"}, {"text": "No coating or chemical on the brake disc or caliper. Tell the customer the rims are coated and what the aftercare is.", "bm": "Tiada salutan atau bahan kimia pada cakera brek atau kaliper. Beritahu pelanggan rim telah disalut dan apa penjagaan selepas servis.", "photo": "", "video": "https://drive.google.com/drive/folders/1X98c9dsCjD8ueeSHGbUtvrfnOzsMJGR2"}]$q$::jsonb, $q$["Detailer", "QC Person", "Junior Technician", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now()),
  ($q$sop-qc$q$, $q$QC$q$, $q$✅$q$, 90, $q$Every car is checked twice by two different people: the department head first, the QC person last. No QC record, no delivery — no exceptions for a busy day. (Handbook 3.5)
Tiada rekod QC, tiada penyerahan.$q$, $q$[{"text": "1st QC: Detailing (wash, polish, coating, interior) → detailing head · PPF & Wrap → PPF & Wrap head · Tint → tint head. Final QC is always the QC person.", "bm": "QC pertama: Detailing → ketua detailing · PPF & Wrap → ketua PPF & Wrap · Tinted → ketua tinted. QC akhir sentiasa petugas QC.", "photo": "", "video": "https://drive.google.com/drive/folders/1bjMHpOtECACgtm1u3Vgob8GuyqLwOlPg"}, {"text": "NOBODY FIRST-CHECKS THEIR OWN WORK. If the head did the job, another head or the QC person runs the 1st QC.", "bm": "TIADA SESIAPA MEMERIKSA KERJA SENDIRI DALAM PEMERIKSAAN PERTAMA. Jika ketua yang membuat kerja itu, ketua lain atau petugas QC yang menjalankan QC pertama.", "photo": "", "video": "https://drive.google.com/drive/folders/1E015sHyam26Dq4nf6pUKpCfuQRH5zRll"}, {"text": "The technician self-inspects first, then calls the head.", "bm": "Juruteknik memeriksa sendiri dahulu, kemudian memanggil ketua.", "photo": "", "video": "https://drive.google.com/drive/folders/1M81XVhgaDfYg7515aYFVcqb0V_ApLYC9"}, {"text": "Check under the detailing lights. Never daylight, never a torch.", "bm": "Di bawah lampu detailing. Jangan guna cahaya siang, jangan guna lampu suluh.", "photo": "", "video": "https://drive.google.com/drive/folders/1MU_fy_iftzr8D4TCZj0N7-wkuL6HtMwY"}, {"text": "Run the checklist for the services that were actually sold. PASS, FAIL or N/A on every line — nothing left blank.", "bm": "Jalankan senarai semak untuk perkhidmatan yang benar-benar dijual. LULUS, GAGAL atau TIDAK BERKENAAN untuk setiap baris - tiada yang dibiarkan kosong.", "photo": "", "video": "https://drive.google.com/drive/folders/11-gxLQJiichWOXfHY_IuoHwmpFuMd41y"}, {"text": "On a FAIL: put MASKING TAPE on the spot, and record what is wrong, who applied that panel, and a photo. All three.", "bm": "Jika GAGAL: letakkan PITA PENUTUP pada tempat itu, dan rekodkan apa yang salah, siapa yang membuat panel itu, dan gambar. Ketiga-tiganya.", "photo": "", "video": "https://drive.google.com/drive/folders/1KILU-OeplonjhGQkQsNVi7BPzUVjM1wq"}, {"text": "The car goes back to the technician with the tape still on it. The head does not release the car — only final QC does.", "bm": "Kereta dihantar balik kepada juruteknik dengan pita masih melekat. Ketua tidak melepaskan kereta. Hanya QC akhir yang boleh.", "photo": "", "video": "https://drive.google.com/drive/folders/1jdr9nvnbAbJPeB0KYp3E4rvQxJfhHBWi"}, {"text": "Rework: the technician fixes every taped spot. THE TECHNICIAN DOES NOT REMOVE THE TAPE. When done, tell the head; the head confirms before calling final QC.", "bm": "Juruteknik membaiki setiap tempat yang berpita. JURUTEKNIK TIDAK MENANGGALKAN PITA. Apabila selesai, beritahu ketua. Ketua mengesahkan sebelum memanggil QC akhir.", "photo": "", "video": "https://drive.google.com/drive/folders/1uobIkcPF68SHOmLLLMxdbTOK4dClE9Uu"}, {"text": "Final QC: re-check every taped spot AND re-run the full check on any reworked panel — rework creates new defects.", "bm": "Periksa semula setiap tempat yang berpita. JUGA jalankan semula pemeriksaan penuh pada mana-mana panel yang dikerjakan semula. Kerja ulang menghasilkan kecacatan baharu.", "photo": "", "video": "https://drive.google.com/drive/folders/1d0ajJ0Yf1Kz1qp9Jjym4Yl8rOj4Y9e0x"}, {"text": "Clear: the QC person removes the tape, marks the pass and releases the car. Not clear: tape it again, record a REMARK, send it back to rework.", "bm": "Jika bersih: tanggalkan pita sendiri, tandakan lulus, lepaskan kereta. Jika tidak bersih: pita semula, rekodkan CATATAN, dan hantar balik ke peringkat 2.", "photo": "", "video": "https://drive.google.com/drive/folders/10qwXWsLK3gF2MeRsPEFy1Ah7JrKmP-RR"}, {"text": "Tape NEVER goes on a fresh coating inside its cure window, or where it will lift a film edge — tape the adjacent glass or trim and note the location instead. Tape still on a car means it is not finished.", "bm": "Pita JANGAN SEKALI-KALI diletak pada salutan baharu dalam tempoh pengeringannya, atau di tempat yang akan mengangkat tepi filem. Letak pita pada cermin atau trim bersebelahan dan catat lokasinya. Pita yang masih ada bermakna kereta itu belum siap.", "photo": "", "video": "https://drive.google.com/drive/folders/1RMQMFmboAnEUjfwPT0jgQzo03ytC4n0v"}, {"text": "A catch at the 1st QC costs NO job points. A car that fails FINAL QC means zero points for that job. The same defect failing final QC twice goes to the manager.", "bm": "Tangkapan pada QC pertama TIDAK merugikan mata kerja. Kereta yang GAGAL QC akhir bermakna sifar mata untuk kerja itu. Kecacatan sama gagal QC akhir dua kali - beritahu pengurus.", "photo": "", "video": "https://drive.google.com/drive/folders/1MzhPxsXzX7RFCNYEycXmf6yXj4Assbto"}, {"text": "Every failure names a person and carries a photo. QC that bends under pressure is worth nothing. Film work gets BOTH QC passes and the printed A5 proof.", "bm": "Setiap kegagalan menamakan seseorang dan disertakan gambar. QC yang tunduk kepada tekanan tidak bernilai. Kerja filem mendapat KEDUA-DUA pemeriksaan QC dan bukti A5 bercetak.", "photo": "", "video": "https://drive.google.com/drive/folders/15QW6DUR_NzAaurLig3Jytht8UFvh2t3p"}]$q$::jsonb, $q$["Detailer", "PPF / Wrap Installer", "Tinted Installer", "QC Person", "Junior Technician", "Senior Technician"]$q$::jsonb, 1, true, 'jimmy', now())
on conflict (id) do update set title=excluded.title, icon=excluded.icon, sort=excluded.sort, intro=excluded.intro,
  steps=excluded.steps, audience=excluded.audience, active=true, updated_by=excluded.updated_by, updated_at=excluded.updated_at;
